import clsx from 'clsx';
import React, {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useState,
} from 'react';
import { useIntl } from 'react-intl';
import type { RequireAtLeastOne } from 'type-fest';

import { CalendarIcon } from '@dynatrace/strato-icons';

import { dateRangeSelectorCSS } from './DateRangeSelector.sty.js';
import { isEqualRangeSelection } from './helpers.js';
import type { DateRangeSelectorProps, DateRangeSelectorRef } from './types.js';
import { Button } from '../../buttons/button/Button.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import { useFocusRing } from '../../core/styles/useFocusRing.js';
import type { TimeframeV2 } from '../../core/types/time.js';
import { useOverlayWithTrigger } from '../../overlays/hooks/useOverlayWithTrigger.js';
import { Overlay } from '../../overlays/overlay/Overlay.js';
import { globalSprinkles } from '../../styles/safe-sprinkles.js';
import { _Calendar as Calendar } from '../date-picker/calendar/Calendar.js';

/**
 * Calendar widget trigger and overlay component.
 */
export const DateRangeSelector = forwardRef<
  DateRangeSelectorRef,
  DateRangeSelectorProps
>((props, forwardedRef) => {
  const {
    value,
    onChange,
    disabled,
    readOnly,
    error,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
    min,
    max,
    ...remainingProps
  } = props;
  const [open, setOpen] = useState(false);
  const [calendarValue, setCalendarValue] = useState(value);

  const intl = useIntl();
  const calendarTriggerLabel = intl.formatMessage({
    defaultMessage: 'DateRangePicker calendar trigger',
    id: 'K2M82PM/gcTo3fjq',
    description: 'Text shown for the datetimerangepicker calendar trigger.',
  });

  // update calendar value state and call onChange if necessary
  const updateCalendarValue = useCallback(
    (newInternalValue) => {
      if (readOnly) {
        return;
      }
      if (!newInternalValue) {
        onChange(null);
      } else if (newInternalValue.from && newInternalValue.to) {
        setOpen(false);
        !isEqualRangeSelection(newInternalValue, value) &&
          onChange(newInternalValue);
      }
      setCalendarValue(newInternalValue);
    },
    [readOnly, onChange, value],
  );

  // apply controlled value update to the calendar value if necessary
  useEffect(() => {
    setCalendarValue((prevValue) =>
      isEqualRangeSelection(prevValue, value) ? prevValue : value,
    );
  }, [value]);

  const {
    targetRef,
    triggerRef,
    overlayRef,
    overlayState,
    overlayProps,
    overlayTriggerProps,
  } = useOverlayWithTrigger({
    placement: 'bottom-end',
    offset: 8,
    trapFocus: false,
    shouldCloseOnBlur: false,
    open,
    onOpenChange: setOpen,
    disabled,
  });

  const rootRef = useMergeRefs([triggerRef, targetRef]);

  useImperativeHandle(
    forwardedRef,
    () => ({
      open: () => setOpen(true),
      close: () => setOpen(false),
    }),
    [],
  );

  const { focusClassName } = useFocusRing({
    focusWithin: false,
    isMinimal: false,
    disabled: disabled,
    variant: error ? 'critical' : 'neutral',
  });

  return (
    <>
      <Button
        ref={rootRef}
        data-testid={dataTestId}
        className={clsx(
          dateRangeSelectorCSS,
          focusClassName,
          consumerClassName,
        )}
        style={consumerStyle}
        aria-label={calendarTriggerLabel}
        {...remainingProps}
        {...overlayTriggerProps}
        size="condensed"
        color={error ? 'critical' : 'neutral'}
        disabled={disabled}
        variant="emphasized"
      >
        <Button.Prefix>
          <CalendarIcon />
        </Button.Prefix>
      </Button>
      <Overlay
        ref={overlayRef}
        isOpen={overlayState.isOpen}
        overlayProps={overlayProps}
        className={globalSprinkles({
          paddingLeft: 16,
          paddingTop: 16,
          paddingRight: 16,
          paddingBottom: 16,
        })}
      >
        <Calendar
          value={
            calendarValue?.from || calendarValue?.to
              ? (calendarValue as RequireAtLeastOne<TimeframeV2>)
              : null
          }
          type="range"
          onChange={updateCalendarValue}
          required={false}
          min={min}
          max={max}
        />
      </Overlay>
    </>
  );
});
